-- ============================================================================
-- Catálogo de add-ons de la suite en BORRADOR (mapeo del 2026-11-16)
-- ----------------------------------------------------------------------------
-- Auditoría 2026-11-16: las apps ya venden o tienen preparados add-ons con
-- precio (agentes de IA de EWM, canales de eChange, Caja/Liquidaciones de
-- eExpense…) que el catálogo del Admin Maestro no conocía. Esta migración los
-- registra como DRAFT con el precio de referencia que hoy tiene cada app en
-- `price_month` (informativo, legacy) y la fuente en la descripción.
--
-- DRAFT = no se puede activar en un tenant ni se factura (catalog_items_
-- available_derived_ck): la tarifa real se fija app por app en
-- catalog_item_prices cuando el área comercial la apruebe, y entonces se
-- publica. Nada aquí cambia lo que un cliente tiene ni lo que paga.
--
-- Códigos `<producto>_<add-on>` para no chocar entre apps. Idempotente:
-- un código que ya existe no se toca (ON CONFLICT DO NOTHING).
-- Mapa legible: docs/commercial/MAPA_ADDONS_SUITE.md.
-- ============================================================================

insert into platform.catalog_items
  (code, name, description, saas_product_id, item_type, scope, price_month, currency, lifecycle_status, billing_model, available)
select v.code, v.name, v.description, p.id, v.item_type, v.scope, v.price_month, v.currency, 'DRAFT', v.billing_model, false
